create table if not exists public.mcp_server_catalog (id uuid primary key default gen_random_uuid(), name text not null, source_type text not null check (source_type in ('remote_url','registry','repository')), server_url text, registry_name text, repository_url text, auth_type text not null default 'none' check (auth_type in ('none','oauth','bearer','api_key')), active boolean not null default true, created_by uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.mcp_server_catalog enable row level security; create policy "authenticated_read_active_mcp_catalog" on public.mcp_server_catalog for select to authenticated using (active = true);
